import{_ as a,o as e,c as i,a2 as l}from"./chunks/framework.CmPiTyN0.js";const u=JSON.parse('{"title":"车载无人机与辅助载具","description":"","frontmatter":{"title":"车载无人机与辅助载具","outline":"deep"},"headers":[],"relativePath":"wiki/uav.md","filePath":"wiki/uav.md","lastUpdated":null}'),r={name:"wiki/uav.md"};function d(o,t,n,h,_,s){return e(),i("div",null,[...t[0]||(t[0]=[l('<p><a href="./../index.html">← 返回 Wiki 首页</a></p><h2 id="_8-车载无人机与辅助载具" tabindex="-1">8. 车载无人机与辅助载具 <a class="header-anchor" href="#_8-车载无人机与辅助载具" aria-label="Permalink to &quot;8. 车载无人机与辅助载具&quot;">​</a></h2><h3 id="_8-1-可部署辅助载具" tabindex="-1">8.1 可部署辅助载具 <a class="header-anchor" href="#_8-1-可部署辅助载具" aria-label="Permalink to &quot;8.1 可部署辅助载具&quot;">​</a></h3><p>部分 RVP 载具可部署辅助载具，并在母车与辅助载具之间切换控制。</p><table tabindex="0"><thead><tr><th>类型</th><th>示例</th></tr></thead><tbody><tr><td>侦察无人机</td><td>SUAV 轻型侦察无人机、四轴侦察无人机</td></tr><tr><td>攻击无人机</td><td>四轴投弹无人机（投掷 PG-7V）、四轴自爆无人机</td></tr><tr><td>无人战车</td><td>龙吼卫（RAWR）无人战斗车</td></tr><tr><td>雷达中继车</td><td>山毛榉-M3 的 96L6 雷达车</td></tr></tbody></table><p>可部署辅助载具的母车：LAV-25、ZBL-08A、ZTZ100、M142 可部署 SUAV 或四轴无人机；LAV-25、ZBL-08A、ZTZ100 还可部署龙吼卫；山毛榉-M3 部署 96L6 雷达车。</p><p>玩法推荐：海玛斯火箭炮放飞侦察无人机，侦察无人机通过侦察吊舱标记敌方载具位置，海玛斯可以通过战术地图上的敌军标记直接发射火箭弹轰炸。</p><p>部署与控制：</p><ul><li>支持部署、切换控制和无人机自动盘旋。</li><li>辅助载具受信号范围限制；超出范围会自动回收。</li><li>重新部署具有冷却时间。</li><li>辅助载具出动期间，母车座位锁定。</li></ul><h3 id="_8-2-山毛榉-m3-雷达车与发射车" tabindex="-1">8.2 山毛榉-M3：雷达车与发射车 <a class="header-anchor" href="#_8-2-山毛榉-m3-雷达车与发射车" aria-label="Permalink to &quot;8.2 山毛榉-M3：雷达车与发射车&quot;">​</a></h3><p>山毛榉-M3 可部署一台 96L6 雷达车：</p><ul><li>部署后可切换控制，两车可分开布置。</li><li>雷达车提供目标信息，发射车负责发射，两车通过数据链联动。</li><li>雷达车可作为雷达中继使用。</li></ul><h3 id="_8-3-舰载直升机着舰" tabindex="-1">8.3 舰载直升机着舰 <a class="header-anchor" href="#_8-3-舰载直升机着舰" aria-label="Permalink to &quot;8.3 舰载直升机着舰&quot;">​</a></h3><ul><li>该功能为实验性功能，只推荐拍视频使用</li><li>目前仅052D 配置直升机停机坪</li><li>直升机接近舰船后按 <code>P</code> 进入自动着舰流程。</li></ul><hr>',15)])])}const c=a(r,[["render",d]]);export{u as __pageData,c as default};
